# --------------------------------------------------------------------------- #
#  Модель даних
# --------------------------------------------------------------------------- #
@dataclass
class EmployeeRecord:
    id: str
    role: str
    name: str
    percent: float
    procedures: List[float] = field(default_factory=list)
    base_rate: float = 0.0
    turnover: float = 0.0
    use_bonus: bool = False
    bonus: float = 0.0
    use_advance: bool = False
    advance: float = 0.0

    @property
    def salary(self) -> float:
        if self.role == "employee":
            base = round(sum(self.procedures) * (self.percent / 100), 2)
        else:
            base = round(self.base_rate + (self.turnover * (self.percent / 100)), 2)
        return round(base + (self.bonus if self.use_bonus else 0.0) - (self.advance if self.use_advance else 0.0), 2)

    @property
    def gross_turnover(self) -> float:
        return sum(self.procedures) if self.role == "employee" else self.turnover

    @property
    def rate_display(self) -> str:
        return f"{self.percent}%" if self.role == "employee" else f"{self.base_rate:.0f} + {self.percent}%"

    @property
    def role_display(self) -> str:
        return "Адміністратор" if self.role == "admin" else "Працівник"

    @property
    def details_display(self) -> str:
        parts = []
        if self.use_bonus and self.bonus > 0: parts.append(f"+Пр:{self.bonus:.0f}")
        if self.use_advance and self.advance > 0: parts.append(f"-Ав:{self.advance:.0f}")
        return " | ".join(parts) if parts else "-"

    def to_dict(self) -> Dict:
        return asdict(self)

    @staticmethod
    def from_dict(d: Dict) -> "EmployeeRecord":
        return EmployeeRecord(**d)


# --------------------------------------------------------------------------- #
#  Генератор PDF-звітів
# --------------------------------------------------------------------------- #
def resolve_cyrillic_font_path() -> Optional[str]:
    candidates = [
        "C:\\Windows\\Fonts\\arial.ttf",
        "/usr/share/fonts/truetype/dejavu/DejaVuSans.ttf",
        "/System/Library/Fonts/Supplemental/Arial.ttf",
    ]
    for path in candidates:
        if os.path.exists(path): return path
    return None

class UkrainianPDF(FPDF):
    def __init__(self, font_path: str, title_text: str = 'РОЗРАХУНКОВИЙ ЛИСТОК ЗАРПЛАТИ'):
        super().__init__()
        self.title_text = title_text
        if font_path:
            self.add_font("CyrillicFont", "", font_path, uni=True)
            self.add_font("CyrillicFont", "B", font_path, uni=True)
        else:
            self.add_font("CyrillicFont", "", "Arial", uni=True)
            self.add_font("CyrillicFont", "B", "Arial", uni=True)

    def header(self):
        self.set_font('CyrillicFont', 'B', 15)
        self.cell(0, 10, self.title_text, ln=True, align='C')
        self.ln(3)

def generate_employee_pdf(record: EmployeeRecord, period_str: str, salon_name: str, file_path: str):
    font_path = resolve_cyrillic_font_path()
    pdf = UkrainianPDF(font_path)
    pdf.add_page()
    pdf.set_font("CyrillicFont", "B", 12)
    pdf.cell(0, 7, f"Салон: {salon_name}", ln=True)
    pdf.cell(0, 7, f"Період: {period_str}", ln=True)
    pdf.cell(0, 7, f"Співробітник: {record.name} ({record.role_display})", ln=True)
    pdf.ln(5)
    pdf.line(10, pdf.get_y(), 200, pdf.get_y())
    pdf.ln(5)

    if record.role == "employee":
        pdf.set_font("CyrillicFont", "B", 11)
        pdf.cell(0, 7, "Виконані процедури:", ln=True)
        pdf.set_font("CyrillicFont", "", 10)
        for idx, proc in enumerate(record.procedures, start=1):
            pdf.cell(100, 6, f"  • Процедура №{idx}", border=0)
            pdf.cell(0, 6, f"{proc:.2f} грн", ln=True)
    else:
        pdf.set_font("CyrillicFont", "B", 11)
        pdf.cell(0, 7, "Дані адміністратора:", ln=True)
        pdf.set_font("CyrillicFont", "", 10)
        pdf.cell(0, 6, f"  • Ставка: {record.base_rate:.2f} грн", ln=True)
        pdf.cell(0, 6, f"  • Обіг салону: {record.turnover:.2f} грн", ln=True)
        pdf.cell(0, 6, f"  • Відсоток від обігу: {record.percent}%", ln=True)
        
    pdf.ln(8)
    pdf.set_font("CyrillicFont", "B", 13)
    pdf.cell(0, 10, f"РАЗОМ ДО ВИПЛАТИ:  {record.salary:.2f} грн", border=1, ln=True, align='C')
    pdf.output(file_path)

def generate_all_employees_pdf(records: List[EmployeeRecord], period_str: str, salon_name: str, file_path: str):
    font_path = resolve_cyrillic_font_path()
    pdf = UkrainianPDF(font_path, title_text="ЗАГАЛЬНА ВІДОМІСТЬ ЗАРПЛАТИ")
    pdf.add_page()
    pdf.set_font("CyrillicFont", "B", 12)
    pdf.cell(0, 7, f"Салон: {salon_name}", ln=True)
    pdf.cell(0, 7, f"Період: {period_str}", ln=True)
    pdf.ln(5)
    pdf.line(10, pdf.get_y(), 200, pdf.get_y())
    pdf.ln(5)

    total_salary = 0.0
    for record in records:
        pdf.set_font("CyrillicFont", "B", 11)
        pdf.cell(0, 7, f"{record.name} ({record.role_display})", ln=True)
        pdf.set_font("CyrillicFont", "", 10)
        
        if record.role == "employee":
            pdf.cell(0, 6, f"  Виробіток: {record.gross_turnover:.2f} грн, Відсоток: {record.percent}%", ln=True)
        else:
            pdf.cell(0, 6, f"  Ставка: {record.base_rate:.2f} грн, Обіг: {record.turnover:.2f} грн, Відсоток: {record.percent}%", ln=True)
            
        details = []
        if record.use_bonus and record.bonus > 0: details.append(f"Премія: +{record.bonus:.2f}")
        if record.use_advance and record.advance > 0: details.append(f"Аванс: -{record.advance:.2f}")
        if details:
            pdf.cell(0, 6, f"  Додатково: {', '.join(details)}", ln=True)

        pdf.set_font("CyrillicFont", "B", 10)
        pdf.cell(0, 6, f"  До виплати: {record.salary:.2f} грн", ln=True)
        pdf.ln(3)
        total_salary += record.salary

    pdf.line(10, pdf.get_y(), 200, pdf.get_y())
    pdf.ln(5)
    pdf.set_font("CyrillicFont", "B", 12)
    pdf.cell(0, 10, f"ЗАГАЛЬНИЙ ФОНД ЗАРПЛАТИ: {total_salary:.2f} грн", border=1, ln=True, align='C')
    pdf.output(file_path)


